@app.get("/", status_code=status.HTTP_200_OK)
def get_books():
    return BOOKS


@app.post("/add_book", status_code=status.HTTP_201_CREATED)
def add_book(book: Book):
    new = Book(**book.model_dump())
    BOOKS.append(find_book_id(new))
    return f'Book of title {new.title} is uploaded successfully'


def find_book_id(book: Book):
    book.id = 1 if len(BOOKS) == 0 else BOOKS[-1].id + 1
    return book


@app.get("/book/{id}", status_code=status.HTTP_200_OK)
def get_book_by_id(id: int = Path(gt=0)):
    for BOOK in BOOKS:
        if BOOK.id == id:
            return BOOK
    raise HTTPException(status_code=404, detail=f'Book of id {id} not found')


@app.get("/book", status_code=status.HTTP_200_OK)
def get_book_by_rating(rating: float = Query(ge=0, le=5)):
    rating_books = []
    for book in BOOKS:
        if book.rating == rating:
            rating_books.append(book)
    if len(rating_books) > 0:
        return rating_books
    raise HTTPException(status_code=404, detail=f"Book of rating {rating} not found")


@app.put("/book/update", status_code=status.HTTP_204_NO_CONTENT)
def update_book(book: Book):
    for i in range(len(BOOKS)):
        prev_book = BOOKS[i]
        if BOOKS[i].id == book.id:
            BOOKS[i] = book
            return f'Book [{prev_book}] is changed to [{book}]'
    raise HTTPException(status_code=404, detail=f"Book {book} not found")


@app.delete("/book/{id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_book_by_id(id: int = Path(gt=0)):
    for i in range(len(BOOKS)):
        if BOOKS[i].id == id:
            del BOOKS[i]
            return f"Book of id {id} got deleted"
    raise HTTPException(status_code=404, detail=f"Book of id {id} not found")


@app.get("/book/pub_year/{year}", status_code=status.HTTP_200_OK)
def get_books_by_published_year(year: int = Path(gt=0)):
    year_books = []
    for book in BOOKS:
        if book.published_year == year:
            year_books.append(book)
    if len(year_books) > 0:
        return year_books
    raise HTTPException(status_code=404, detail=f'No books found published in year {year}')
